        else
            title = "Other Sport: ";
        this.ltrHeaderStr.Text = "<!--excel-export--><b>" + title +  Resources.Language.TraderPerformanceDetail;


        if (Request.Form["export"] != null)
        {
            isExportExcel = true;
        }

        this.ltrContentHtml.Text = BuildReport(Request["sortCol"], Request["order"], IsSoccer) + "<!--/excel-export-->";

        if (isExportExcel)
        {
            ExportToExcel(Response, ltrHeaderStr.Text + ltrContentHtml.Text, "TraderPerformanceDetail");
        }
    }

    public static void ExportToExcel(HttpResponse Response, string data, string filename)
    {
        Response.Clear();
        Response.AddHeader("content-disposition", "attachment;filename=" + filename.Replace(" ", "") + ".xls");
        Response.Charset = "utf-8";
        Response.ContentType = "application/vnd.xls";

        StringBuilder content = new StringBuilder();

        content.AppendLine("<style>");
        content.AppendLine("body{font-family:Tahoma; font-size:11px; color:#000000; background:#ffffff;}");
        content.AppendLine("td,table{border-color:gray}");
        content.AppendLine("tr.report-header{color:#ffffff; background:#536B81;font-size:11px;font-weight:bold;text-align:center}");
        content.AppendLine("tr.report-row-odd{background:#DFEAFF;font-size:11px;}");
        content.AppendLine("tr.report-row-even{background:#ffffff;font-size:11px;}");
        content.AppendLine("tr.report-row-total1{background:#CCFFCC;font-weight:bold;font-size:11px;}");
        content.AppendLine(".ralign{text-align:right;font-size:11px;}");
        content.AppendLine(".lalign{text-align:left;font-size:11px;}");
        content.AppendLine(".calign{text-align:center;font-size:11px;}");
        content.AppendLine(".a1{background-color: #CCFFFF !important;}");
        content.AppendLine(".a2{background-color: #FFFF99 !important;}");
        content.AppendLine(".a3{background-color: #ffffee !important;}");
        content.AppendLine(".a4{background-color: #FFDDFF !important;}");
        content.AppendLine(".a5{background-color: #ffffff !important;}");
        content.AppendLine("</style>");

        string strRpt = TemplateHandler.CopyBlock(data, "excel-export");
        TemplateHandler.RemoveBlock(ref strRpt, "not-excel-export");
        content.AppendLine(strRpt);
        content.Append("<table><tr><td></td></tr></table>");

        content.Replace("href=\"", "href=\"#");
        content.Replace("href='", "href='#");

        Response.Write(content.ToString());
        Response.End();
    }

